('personality','Extraversion','How quickly do you make new friends?',
	'[{"id":"a8","label":"Very slowly"},{"id":"b8","label":"Slowly"},{"id":"c8","label":"At an average pace"},{"id":"d8","label":"Very quickly and easily."}]','d8'),
('personality','Extraversion','Do you describe yourself as generally cheerful and high-spirited?',
	'[{"id":"a9","label":"No, rarely cheerful"},{"id":"b9","label":"Occasionally cheerful"},{"id":"c9","label":"Often cheerful"},{"id":"d9","label":"Yes, I am generally very cheerful."}]','d9'),
('personality','Extraversion','Do you prefer activities that are calm and quiet, or exciting and fast-paced?',
