('personality','Extraversion','Do you often feel energized and motivated by competition?',
	'[{"id":"a13","label":"Not at all"},{"id":"b13","label":"A little"},{"id":"c13","label":"Sometimes"},{"id":"d13","label":"Yes, I thrive on competition."}]','d13'),
('personality','Extraversion','Do you tend to walk or move quickly, or slowly and deliberately?',
	'[{"id":"a14","label":"Very slowly"},{"id":"b14","label":"Slowly"},{"id":"c14","label":"Average pace"},{"id":"d14","label":"Quickly and energetically (High Activity)."}]','d14'),
('personality','Extraversion','Do you naturally take on leadership roles in temporary groups or social settings?',
	'[{"id":"a15","label":"No"},{"id":"b15","label":"Rarely"},{"id":"c15","label":"Sometimes"},{"id":"d15","label":"Yes, I naturally assume a leadership role."}]','d15'),
('personality','Extraversion','Do you often talk louder than most other people?',
